<section class="threat-workspace"><div class="mode-banner"><div><span class="eyebrow">DETECTION ENGINE</span><h2>Active protection rules</h2><small>Evaluated on each collected event / ten-minute duplicate suppression</small></div><div class="mode-actions"><span class="state-tag"><?=count($rules)?> rules active</span><div class="export-actions"><a class="button export-button" href="?export=threats&amp;format=csv"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 3v12m0 0 4-4m-4 4-4-4M5 17v3h14v-3"/></svg>CSV</a><a class="button export-button docx-button" href="?export=threats&amp;format=docx"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M7 3h7l5 5v13H7a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2Zm7 0v5h5M9 13h6m-6 4h6"/></svg>DOCX</a></div></div></div><div class="rule-tools"><label>Find a rule<input id="rule-search" placeholder="Search rules or conditions"></label><label>Show<select id="rule-kind"><option value="">All activity types</option><option value="AUTH">Authentication</option><option value="ACCESS">Access control</option><option value="BEHAVIOR">User activity</option></select></label></div><div class="detection-grid"><?php foreach($rules as $rule):$q=$db->prepare('SELECT COUNT(*) FROM incidents WHERE title LIKE ?');$prefix=$rule[1];$q->execute([$prefix]);$matches=(int)$q->fetchColumn();?><article class="panel detection-card" data-rule="<?=h($rule[0])?>"><header><span class="rule-code"><?=h($rule[0])?></span><span class="severity <?=strtolower($rule[3])?>"><?=h($rule[3])?></span></header><h3><?=h($rule[1])?></h3><p><?=h($rule[2])?></p><div class="rule-result"><strong><?=$matches?></strong><span>recorded incidents</span><span class="state-tag">Enabled</span></div><details><summary>Rule behavior</summary><p>A match creates an incident at the displayed priority and a local alert. Repeated matches from the same account, IP and rule are grouped for ten minutes. A new IP or browser is a review signal, not proof of account compromise. Login limits and route validation are enforced separately; these rules do not block an IP globally.</p></details></article><?php endforeach;?></div><div class="notice"><b>Rule configuration</b><span>These are the implemented application rules. Editing thresholds or disabling rules is not available in this interface.</span></div><?php panel_start('Recent detection matches','Source evidence and locally generated alerts');live_table(['INCIDENT','TIME','RULE','ACCOUNT','IP','ALERT'],$db->query('SELECT i.id,i.created_at,i.title,e.user_identifier,e.source_ip,a.id FROM incidents i LEFT JOIN security_events e ON i.event_id=e.id LEFT JOIN security_alerts a ON a.incident_id=i.id ORDER BY i.id DESC LIMIT 20')->fetchAll(PDO::FETCH_NUM));?></article><script>(()=>{const apply=()=>{const term=document.getElementById('rule-search').value.toLowerCase(),kind=document.getElementById('rule-kind').value;document.querySelectorAll('[data-rule]').forEach(card=>card.hidden=!card.textContent.toLowerCase().includes(term)||!card.dataset.rule.startsWith(kind));};document.getElementById('rule-search').addEventListener('input',apply);document.getElementById('rule-kind').addEventListener('change',apply);})();</script>
</section>